<template><section class="g-resource-tree"><el-input v-model="keyword" clearable placeholder="搜索资源" @input="tree?.filter(keyword)"/><el-tree ref="tree" :data="data" :props="props" node-key="id" highlight-current :filter-node-method="filterNode" @node-click="$emit('select',$event)"/></section></template><script setup lang="ts">import{ref}from'vue';import type{ElTree}from'element-plus';withDefaults(defineProps<{data:Record<string,unknown>[];props?:{label:string;children:string}}>(),{props:()=>({label:'label',children:'children'})});defineEmits<{(e:'select',node:Record<string,unknown>):void}>();const keyword=ref('');const tree=ref<InstanceType<typeof ElTree>>();const filterNode=(value:string,data:any)=>!value||String(data.label||'').toLowerCase().includes(value.toLowerCase());</script><style scoped src="./style.scss"></style>
